def control(o):
    h=o['hitch_deg']
    v=o.get('views',{})
    pts=[]
    for name in ('direct','periphery'):
        view=v.get(name) or {}
        x0,y0=view.get('origin',[0.1,0])
        for b,d in view.get('walls',[]):
            r=math.radians(b); x=x0+d*math.cos(r); y=y0+d*math.sin(r)
            if -3.5<x<-0.5 and abs(y)<3: pts.append((x,y))
    left=[y for x,y in pts if y>0.5]; right=[y for x,y in pts if y< -0.5]
    offset=0
    if left and right: offset=(min(left)+max(right))/2
    desired=max(-8,min(8,-offset*10))
    steer=max(-35,min(35,2.4*(h-desired)))
    return (steer,-0.45,170)

